code_example:
int data1 = 10, data2 = 20;

// Pointer to const data (Data immutable)
const int* p_to_const = &data1;
// *p_to_const = 5;    // ERROR: Data read-only
p_to_const = &data2;     // OK: Pointer reassignment

// Const pointer (Pointer immutable)
int* const const_ptr = &data1;
*const_ptr = 5;          // OK: Data modification
// const_ptr = &data2; // ERROR: Pointer immutable

// Const pointer to const data (Both immutable)
const int* const fully_const = &data1;
// *fully_const = 5;     // ERROR
// fully_const = &data2; // ERROR
